WITH valid_orders AS (SELECT member_id, date_trunc('month', ordered_at) AS stat_month, paid_cents, refund_cents FROM {{ ref('orders') }} WHERE status = 'paid' AND paid_cents - refund_cents > 0), agg AS (SELECT member_id, stat_month, COUNT(*) AS valid_order_cnt, SUM(paid_cents - refund_cents) AS net_sales_cents FROM valid_orders GROUP BY member_id, stat_month), eligible AS (SELECT a.member_id, a.stat_month FROM agg a WHERE EXISTS (SELECT 1 FROM {{ ref('cards') }} c WHERE c.member_id = a.member_id AND c.card_type IN ('悦享年卡','家庭季卡') AND c.valid_from <= last_day(a.stat_month) AND c.valid_until > last_day(a.stat_month) AND (c.ended_at IS NULL OR c.ended_at > last_day(a.stat_month)))) SELECT a.member_id || '-' || strftime(a.stat_month, '%Y-%m') AS member_month, a.member_id, a.stat_month, CASE WHEN e.member_id IS NULL THEN FALSE ELSE TRUE END AS eligible, a.valid_order_cnt, a.net_sales_cents FROM agg a LEFT JOIN eligible e ON a.member_id = e.member_id AND a.stat_month = e.stat_month